// Separate purchase intent from RFQs. No payments or customer data are transmitted.
const shoppingStorageKey='lepetse-shopping-cart-v1';
let shoppingStorageUnavailable=false;
let shoppingCart=(()=>{try{const raw=JSON.parse(localStorage.getItem(shoppingStorageKey)||'[]');return Array.isArray(raw)?raw.slice(0,250).filter(x=>products.some(p=>p.id===x.productId)&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=999999).map(x=>({productId:x.productId,quantity:x.quantity})):[]}catch{return []}})();
const selectedPaymentProvider=Object.freeze({id:'peach-payments',name:'Peach Payments',plan:'Growth',integration:'orchestration-hosted-checkout',activation:'pending-registration'});
let checkoutDraft={},checkoutReview=false;
function rfqBuyer(){const buyer=new URLSearchParams(location.hash.split('?')[1]||'').get('buyer');return ['business','government'].includes(buyer)?buyer:''}
function rfqHref(route){return '#'+route+(rfqBuyer()?'?mode=quote&buyer='+rfqBuyer():'')}
function syncRfqNavigation(){document.querySelectorAll('header a[href^="#basket"],.mobile-basket').forEach(a=>{a.href=rfqHref('basket');a.innerHTML=(rfqBuyer()?'RFQ basket ':'Quote basket ')+'<span class="basket-count">'+(items.length?'('+items.length+')':'')+'</span>'})}
function quotationMode(){return new URLSearchParams(location.hash.split('?')[1]||'').get('mode')==='quote'}
function quoteModeQuery(){const p=new URLSearchParams(location.hash.split('?')[1]||'');return 'mode=quote'+(['business','government'].includes(p.get('buyer'))?'&buyer='+p.get('buyer'):'')}
function productIntentHref(id){return '#product-'+id+(quotationMode()?'?'+quoteModeQuery():'')}
function purchaseLabel(p,detail=false){return rfqBuyer()&&quotationMode()?'Add to RFQ':quotationMode()||!priceReferences[p.id]?(detail?'Add to quote basket':'Add to quote'):'Add to cart'}
function saveShoppingCart(){try{if(shoppingCart.length)localStorage.setItem(shoppingStorageKey,JSON.stringify(shoppingCart));else localStorage.removeItem(shoppingStorageKey)}catch{shoppingStorageUnavailable=true}document.querySelectorAll('.cart-count').forEach(e=>e.textContent=shoppingCart.length?'('+shoppingCart.length+')':'')}
function addShoppingProduct(id,quantity){if(!Number.isInteger(quantity)||quantity<1||quantity>999999){toast('Enter a whole quantity between 1 and 999,999.');return}const p=products.find(p=>p.id===id);if(!p)return;const line=shoppingCart.find(x=>x.productId===id),total=(line?.quantity||0)+quantity;if(total>999999||(!line&&shoppingCart.length>=250)){toast('The cart limit has been reached. Review your cart.');return}if(line)line.quantity=total;else shoppingCart.push({productId:id,quantity});checkoutReview=false;saveShoppingCart();const d=$('#basket-dialog');d.innerHTML=`<h2 id="basket-dialog-title">Added to your shopping cart</h2><p>${esc(p.name)}</p><p>${quantity} × ${esc(p.unit)} added. Cart quantity: ${total}.</p><div class="dialog-actions"><button class="btn outline" id="cart-keep">Continue shopping</button><a class="btn dark" id="cart-view" href="#cart">View cart</a></div>`;d.showModal();$('#cart-keep').onclick=()=>d.close();$('#cart-view').onclick=()=>d.close();$('#cart-keep').focus()}
function shoppingTotal(){return shoppingCart.reduce((sum,x)=>sum+(priceReferences[x.productId]?.amountMinor||0)*x.quantity,0)}
function shoppingSummary(){const missing=shoppingCart.filter(x=>!priceReferences[x.productId]).length;return `<div class="basket-price-total"><span>Indicative item subtotal</span><strong>${esc(schoolMoney(shoppingTotal()))}</strong></div><p class="help">${missing?`${missing} item(s) need pricing and are excluded from the subtotal. `:''}Preview prices only. Selling prices, delivery charges and applicable VAT must be confirmed before payment is available.</p>`}
function shoppingCartPage(){return `<section class="catalogue-heading"><div class="wrap"><span class="eyebrow">Shopping</span><h1>Your shopping cart</h1><p>Buying directly? Review your items here. Business and government RFQs use the separate <a href="#basket">quote basket</a>.</p></div></section><section class="section"><div class="wrap basket-layout"><div>${shoppingCart.length?shoppingCart.map((x,i)=>{const p=products.find(p=>p.id===x.productId),price=priceReferences[p.id];return `<article class="basket-item"><div class="basket-thumb">${productArt(p)}</div><div class="basket-description"><h3>${esc(p.name)}</h3><p>Ordering unit: ${esc(p.unit)}</p><p>Indicative unit price: ${price?esc(schoolMoney(price.amountMinor)):'Price by quotation'}</p><p data-cart-line="${i}">Line total: ${price?esc(schoolMoney(price.amountMinor*x.quantity)):'Not available'}</p></div><div><label for="cart-qty-${i}">Quantity</label><input id="cart-qty-${i}" data-cart-qty="${i}" type="number" min="1" max="999999" step="1" value="${x.quantity}"><button class="remove-item" data-cart-remove="${i}">Remove</button></div></article>`}).join('')+'<div class="basket-footer-actions"><a href="#stationery">Continue shopping</a><button id="clear-cart" class="clear-filters">Clear cart</button></div>':'<div class="empty"><h2>Your cart is empty</h2><p>Browse stationery to choose items for direct purchase.</p><a class="btn dark" href="#stationery">Shop stationery</a></div>'}</div><aside class="basket-summary"><h2>Shopping summary</h2><div id="shopping-summary" aria-live="polite">${shoppingSummary()}</div>${shoppingCart.length?'<a class="btn dark" href="#checkout" id="checkout-link">Continue to checkout</a>':''}<p class="help">Checkout preview: no payment is taken and no order is placed.</p><p class="help">${shoppingStorageUnavailable?'Device storage is unavailable. Keep this page open.':'Cart items are saved on this device. Contact and delivery details are not saved.'}</p></aside></div></section>`}
function bindShoppingCart(){main.querySelectorAll('[data-cart-qty]').forEach(input=>{input.oninput=()=>{const valid=input.value&&input.checkValidity();input.setAttribute('aria-invalid',String(!valid));if(valid){shoppingCart[Number(input.dataset.cartQty)].quantity=input.valueAsNumber;saveShoppingCart();checkoutReview=false;const line=shoppingCart[Number(input.dataset.cartQty)],price=priceReferences[line.productId];main.querySelector(`[data-cart-line="${input.dataset.cartQty}"]`).textContent='Line total: '+(price?schoolMoney(price.amountMinor*line.quantity):'Not available')}const invalid=[...main.querySelectorAll('[data-cart-qty]')].some(x=>!x.value||!x.checkValidity());$('#shopping-summary').innerHTML=invalid?'<p>Enter valid whole quantities to calculate the subtotal.</p>':shoppingSummary()}});main.querySelectorAll('[data-cart-remove]').forEach(b=>b.onclick=()=>{shoppingCart.splice(Number(b.dataset.cartRemove),1);saveShoppingCart();checkoutReview=false;main.innerHTML=shoppingCartPage();bindShoppingCart()});$('#checkout-link')?.addEventListener('click',e=>{const bad=[...main.querySelectorAll('[data-cart-qty]')].find(x=>!x.value||!x.checkValidity());if(bad){e.preventDefault();bad.reportValidity()}});$('#clear-cart')?.addEventListener('click',()=>{const d=$('#basket-dialog');d.innerHTML='<h2 id="basket-dialog-title">Clear shopping cart?</h2><p>Your quote basket will be kept.</p><div class="dialog-actions"><button class="btn outline" id="cart-cancel">Keep items</button><button class="btn dark" id="cart-confirm">Clear cart</button></div>';d.showModal();$('#cart-cancel').onclick=()=>d.close();$('#cart-confirm').onclick=()=>{shoppingCart=[];saveShoppingCart();checkoutReview=false;d.close();main.innerHTML=shoppingCartPage();bindShoppingCart()}})}
function checkoutField(name,label,type='text',required=true){return `<div class="field"><label for="checkout-${name}">${label}${required?' *':''}</label><input id="checkout-${name}" name="${name}" type="${type}" value="${esc(checkoutDraft[name]||'')}" ${required?'required':''} maxlength="200" autocomplete="${{contact:'name',email:'email',phone:'tel',address:'street-address',city:'address-level2',province:'address-level1',postcode:'postal-code'}[name]||'off'}"></div>`}
function checkoutPage(){if(!shoppingCart.length)return shoppingCartPage();return `<section class="catalogue-heading"><div class="wrap"><span class="eyebrow">Checkout preview</span><h1>${checkoutReview?'Review your purchase':'Contact and delivery details'}</h1><p>No order is placed or payment taken in this preview.</p></div></section><section class="section"><div class="wrap basket-layout"><div><ol class="checkout-progress" aria-label="Checkout steps"><li ${!checkoutReview?'aria-current="step"':''}>1. Contact & delivery</li><li ${checkoutReview?'aria-current="step"':''}>2. Review</li><li>3. Payment — unavailable</li></ol>${checkoutReview?`<div class="checkout-review"><h2>Contact and delivery</h2><p>${esc(checkoutDraft.contact)}<br>${esc(checkoutDraft.email)}<br>${esc(checkoutDraft.phone)}</p><p>${esc(checkoutDraft.address)}<br>${esc(checkoutDraft.city)}, ${esc(checkoutDraft.province)}<br>${esc(checkoutDraft.postcode)}</p><button id="checkout-edit" class="btn outline">Edit details</button><h2>Items</h2><ul class="checkout-items">${shoppingCart.map(x=>{const p=products.find(p=>p.id===x.productId);return `<li><span>${esc(p.name)}<small>${x.quantity} × ${esc(p.unit)}</small></span><strong>${priceReferences[p.id]?esc(schoolMoney(priceReferences[p.id].amountMinor*x.quantity)):'Price by quotation'}</strong></li>`}).join('')}</ul><h2>Payment</h2><p>Peach Payments is the selected payment provider. Online payment is pending activation. No payment details are collected in this preview.</p><button class="btn dark" disabled>Pay with Peach Payments — unavailable</button></div>`:`<form id="shopping-checkout"><h2>Contact</h2><div class="fields">${checkoutField('contact','Full name')}${checkoutField('email','Email address','email')}${checkoutField('phone','Phone number','tel')}</div><h2>Delivery address</h2><div class="fields">${checkoutField('address','Street address')}${checkoutField('city','Town or city')}${checkoutField('province','Province')}${checkoutField('postcode','Postal code')}</div><p class="help">Delivery availability and charges are still to be confirmed. Your details stay in memory and clear when this page is refreshed.</p><button class="btn dark" type="submit">Review purchase</button></form>`}</div><aside class="basket-summary"><h2>Purchase summary</h2>${shoppingSummary()}<p class="help payment-provider-note"><strong>${esc(selectedPaymentProvider.name)}</strong><br>Online payment pending activation.</p><dl><div><dt>Delivery</dt><dd>To be confirmed</dd></div><div><dt>Final payable total</dt><dd>Not yet available</dd></div></dl><a href="#cart" class="btn outline">Back to cart</a></aside></div></section>`}
function bindCheckout(){const form=$('#shopping-checkout');if(form){form.oninput=()=>{checkoutDraft=Object.fromEntries(new FormData(form))};form.onsubmit=e=>{e.preventDefault();checkoutDraft=Object.fromEntries(new FormData(form));checkoutReview=true;main.innerHTML=checkoutPage();bindCheckout();main.focus();window.scrollTo(0,0)}}$('#checkout-edit')?.addEventListener('click',()=>{checkoutReview=false;main.innerHTML=checkoutPage();bindCheckout()})}
